consts.signature:
const (
	// Document is the root node of a parsed CommonMark document.
	Document NodeType = iota
	// Paragraph is a run of inline content rendered as <p>.
	Paragraph
	// Heading is an ATX or setext heading; Level holds 1-6.
	Heading
	// BlockQuote is a "> " quoted region.
	BlockQuote
	// List is a bullet or ordered list; see Info, Level and Tight.
	List
	// Item is a single list item.
	Item
	// CodeBlock is an indented or fenced code block; Literal holds the code
	// and Info the fenced info string.
	CodeBlock
	// HTMLBlock is a run of raw HTML at block level; Literal holds it verbatim.
	HTMLBlock
	// ThematicBreak is a horizontal rule.
	ThematicBreak
	// Text is a literal run of text.
	Text
	// Emph is emphasized inline content, rendered as <em>.
	Emph
	// Strong is strongly emphasized inline content, rendered as <strong>.
	Strong
	// Link is a hyperlink; see Destination and Title.
	Link
	// Image is an image reference; see Destination and Title.
	Image
	// Code is an inline code span; Literal holds its contents.
	Code
	// HTMLInline is a raw inline HTML tag; Literal holds it verbatim.
	HTMLInline
	// SoftBreak is a line ending inside a paragraph.
	SoftBreak
	// HardBreak is an explicit line break, rendered as <br />.
	HardBreak
)

consts.doc:
The node types produced by [Parse]. The first nine are block-level nodes;
the remainder are inline nodes and may only appear inside a Paragraph,
Heading, Link or Image (or nested inline) node.

types.signature:
type Options struct {
	// HTML allows raw HTML blocks and inline HTML through to the output.
	// CommonMark requires this (default true for the package-level Render).
	// When false, raw HTML is escaped rather than passed through.
	HTML bool
	// Typographer enables smart quotes, en/em dashes and ellipses.
	Typographer bool
	// LineBreaks renders soft line breaks inside paragraphs as <br />.
	LineBreaks bool
	// LinkTarget, when non-empty, is emitted as the target attribute of every
	// generated <a> element, e.g. "_blank".
	LinkTarget string
	// ValidateLink decides whether a link destination or image source may be
	// emitted. A destination it rejects is replaced with the empty string.
	//
	// It mirrors markdown-it's overridable md.validateLink hook. When nil the
	// package-level [ValidateLink] is used, which rejects the javascript:,
	// vbscript:, file: and data: schemes (except inert data:image/... payloads).
	// Set it to func(string) bool { return true } to disable sanitizing.
	ValidateLink func(url string) bool
}

examples.code:
package main

import (
	"fmt"

	"github.com/malcolmston/markdown"
)

func main() {
	fmt.Print(markdown.Render("# Title\n\nSome *emphasis* and a [link](/url).\n"))
}

package main

import (
	"fmt"
	"os"

	"github.com/malcolmston/markdown"
)

func main() {
	if err := markdown.RenderTo(os.Stdout, "- a\n- b\n"); err != nil {
		fmt.Println("error:", err)
	}
}

package main

import (
	"fmt"

	"github.com/malcolmston/markdown"
)

func main() {
	fmt.Print(markdown.Render("[click](javascript:alert(1))\n"))
	fmt.Print(markdown.Render("![logo](data:image/png;base64,iVBORw0KGgo=)\n"))
	fmt.Println(markdown.ValidateLink("https://example.com"), markdown.ValidateLink("vbscript:x"))
}

package main

import (
	"fmt"

	"github.com/malcolmston/markdown"
)

func main() {
	md := markdown.New(markdown.Options{
		HTML:        true,
		Typographer: true,
		LinkTarget:  "_blank",
	})
	fmt.Print(md.Render(`He said "hi" -- then [left](/away).` + "\n"))
}

package main

import (
	"fmt"

	"github.com/malcolmston/markdown"
)

func main() {
	doc := markdown.Parse("See [the spec](https://spec.commonmark.org) and [RFC](/rfc).\n")
	doc.Walk(func(n *markdown.Node) bool {
		if n.Type == markdown.Link {
			fmt.Println(n.Destination)
		}
		return true
	})
}

package main

import (
	"fmt"

	"github.com/malcolmston/markdown"
)

func main() {
	doc := markdown.Parse("# One\n\n## Two\n\n### Three\n")
	doc.Walk(func(n *markdown.Node) bool {
		if n.Type == markdown.Heading {
			fmt.Printf("h%d\n", n.Level)
		}
		return true
	})
}

package main

import (
	"fmt"
	"strings"

	"github.com/malcolmston/markdown"
)

func main() {
	md := markdown.New(markdown.Options{
		HTML: true,
		ValidateLink: func(u string) bool {
			return strings.HasPrefix(u, "https://") || strings.HasPrefix(u, "#")
		},
	})
	fmt.Print(md.Render("[a](https://ok/) [b](http://no/) [c](#here)\n"))
}
